## 5.2 `copy-to-demos.mjs` — hashing, manifest, pruning, copies

**File:** `/Users/michael/Development/michaelkrog/Pathland/lib/typescript/scripts/copy-to-demos.mjs`

Lines 22–33:

```js
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = resolve(root, "dist/pathland-dom-renderer.js");
const bundle = readFileSync(source);
const hash = createHash("sha256").update(bundle).digest("hex").slice(0, 12);
const integrity = "sha384-" + createHash("sha384").update(bundle).digest("base64");
const name = `dom-renderer-${hash}.js`;
const manifest = "dom-renderer.current";

const targets = [
  resolve(root, "../java/pathland-quarkus-demo/src/main/resources/META-INF/resources/_pathland"),
  resolve(root, "../java/pathland-spring-boot-demo/src/main/resources/static/_pathland"),
];
```

Lines 35–57 copy the bundle, prune stale `dom-renderer-*.js` / `dom-renderer.js`, write the two-line manifest, and copy the stable `sw.js`:

```js
for (const dir of targets) {
  mkdirSync(dir, { recursive: true });
  for (const entry of readdirSync(dir)) {
    if (entry === name || entry === manifest) continue;
    if (!entry.startsWith("dom-renderer-") && entry !== "dom-renderer.js") continue;
    rmSync(join(dir, entry));
  }
  const dest = resolve(dir, name);
  copyFileSync(source, dest);
  writeFileSync(resolve(dir, manifest), name + "\n" + integrity + "\n");
  copyFileSync(resolve(root, "sw.js"), resolve(dir, "sw.js"));
}
```

Lines 59–69 copy `sw.js` into the **Quarkus extension** as a classpath fallback:

```js
const extensionResources = resolve(
  root,
  "../java/pathland-quarkus/src/main/resources/META-INF/resources/_pathland",
);
mkdirSync(extensionResources, { recursive: true });
copyFileSync(resolve(root, "sw.js"), resolve(extensionResources, "sw.js"));
```

Important: the JS bundle is copied **only into the two demo modules**, not into the starter or the Quarkus extension.

